import inspect
import sys

import pytest
import solution
from hypothesis import given, HealthCheck
import hypothesis.strategies as st
from solution import fibfib


def ref_fibfib(n: int) -> int:
    # Obviously-correct iterative reference model.
    if n == 0 or n == 1:
        return 0
    if n == 2:
        return 1
    a, b, c = 0, 0, 1
    for _ in range(3, n + 1):
        a, b, c = b, c, a + b + c
    return c


# --- concrete examples from the spec docstring ---

def test_example_fibfib_1():
    assert fibfib(1) == 0


def test_example_fibfib_5():
    assert fibfib(5) == 4


def test_example_fibfib_8():
    assert fibfib(8) == 24


def test_spec_base_cases():
    assert fibfib(0) == 0
    assert fibfib(1) == 0
    assert fibfib(2) == 1


def test_spec_first_values_table():
    # Full table derived from the recurrence, cross-checked with reference.
    # 0,0,1,1,2,4,7,13,24,44,81
    expected = [0, 0, 1, 1, 2, 4, 7, 13, 24, 44, 81]
    for n, v in enumerate(expected):
        assert fibfib(n) == v, f"n={n}"


# --- property-based tests (small n so naive impl can still finish) ---

@given(st.integers(min_value=0, max_value=12))
def test_property_matches_reference_model(n):
    assert fibfib(n) == ref_fibfib(n)


@given(st.integers(min_value=3, max_value=12))
def test_property_recurrence_holds(n):
    assert fibfib(n) == fibfib(n - 1) + fibfib(n - 2) + fibfib(n - 3)


@given(st.integers(min_value=0, max_value=12))
def test_property_nonnegative(n):
    assert fibfib(n) >= 0


@given(st.integers(min_value=1, max_value=11))
def test_property_nondecreasing_from_1(n):
    # Sequence from n=1 onward: 0,1,1,2,4,7,13,... is non-decreasing.
    assert fibfib(n + 1) >= fibfib(n)


@given(st.integers(min_value=0, max_value=11))
def test_property_next_value_determined_by_triple(n):
    # Metamorphic: extending the triple (n,n+1,n+2) determines n+3.
    assert fibfib(n + 3) == fibfib(n) + fibfib(n + 1) + fibfib(n + 2)


def test_property_return_type_is_int():
    for n in range(0, 13):
        assert isinstance(fibfib(n), int)


# --- efficiency: spec requires efficient computation ---

def test_property_efficient_for_large_n():
    # The spec says "efficiently compute the n-th element".
    # A naive triple-exponential recursion makes far too many calls.
    # We count top-level entries into solution.fibfib; the recursive
    # calls resolve through the module global, so wrapping the module
    # attribute intercepts them. Abort early instead of hanging.
    n = 30
    expected = ref_fibfib(n)
    assert expected == 29249425

    original = solution.fibfib
    call_count = [0]
    max_calls = 5000

    def counting_wrapper(k):
        call_count[0] += 1
        if call_count[0] > max_calls:
            raise AssertionError(
                f"inefficient implementation: exceeded {max_calls} calls computing fibfib({n})"
            )
        return original(k)

    solution.fibfib = counting_wrapper
    try:
        result = counting_wrapper(n)
    finally:
        solution.fibfib = original

    assert result == expected
    assert call_count[0] <= max_calls
